    legal: ["Legal Notes","ملاحظات قانونية","Rechtliche Hinweise","Avisos legales","Mentions légales","Yasal notlar","法律声明","법적 고지","法的事項","Notis Undang-undang"],
    install: ["Install app","ثبّت التطبيق","App installieren","Instalar la app","Installer l’app","Uygulamayı yükle","安装应用","앱 설치","アプリをインストール","Pasang aplikasi"],
